// Change this to the origin name your log entries should appear under in Administrate
const LOG_ORIGIN_IDENTIFIER = 'Automator Integration';

const logDetails = [
  {
    "details": [
      {
        "type": "text",
        "value": "Automator execution URI: " + `/workflow/${$input.first().json.workflowId || $workflow.id}/executions/${$input.first().json.executionId || $execution.id}`
      }
    ]
  }
];

if ('details' in $input.first().json && $input.first().json.details !== null) {
  logDetails.push({
    "details": [
      {
        "type": "text",
        "value": $input.first().json.details
      }
    ]
  });
}


const payloadData = {"groups": logDetails}

return {
  "nodeId": $input.first().json.nodeId,
  "originIdentifier": LOG_ORIGIN_IDENTIFIER,
  "message": $input.first().json.message,
  "status": $input.first().json.status,
  "payload": JSON.stringify(payloadData),
  "internalLogMetadata": {
    "category": "n8n",
    "subcategory": "automator"
  }
};

