// Change this to the origin name your log entries should appear under in Administrate
const LOG_ORIGIN_IDENTIFIER = 'Automator Integration';

const logDetails = [
  {
    "details": [
      {
        "type": "text",
        "value": "Automator execution URI: " + `/workflow/${$input.first().json.workflow.id || $workflow.id}/executions/${$input.first().json.execution.id || $execution.id}`
      }
    ]
  }
];

logDetails.push({
  "details": [
    {
      "type": "text",
      "value": `Ran "${$input.first().json.workflow.name}" in mode ${$input.first().json.execution.mode} which failed at "${$input.first().json.execution.lastNodeExecuted}".`
    }
  ]
});


const payloadData = {"groups": logDetails}

return {
  "nodeId": $input.first().json.nodeId,
  "originIdentifier": LOG_ORIGIN_IDENTIFIER,
  "message": $input.first().json.execution.error.message,
  "status": "failed",
  "payload": JSON.stringify(payloadData),
  "internalLogMetadata": {
    "category": "n8n",
    "subcategory": "automator"
  }
};
